const cyberPanelAutologinBridge = `<?php
/* CyberPanel signed one-time login bridge. */
add_action('rest_api_init', function () {
  register_rest_route('cyberpanel/v1', '/autologin', array('methods'=>'POST','permission_callback'=>'__return_true','callback'=>function($request){
    $endpoint=get_option('cyberpanel_autologin_endpoint');
    if(!is_string($endpoint)||$endpoint===''){return new WP_Error('disabled','Bridge disabled',array('status'=>403));}
    $response=wp_remote_post($endpoint,array('timeout'=>5,'sslverify'=>true,'headers'=>array('Content-Type'=>'application/json'),'body'=>wp_json_encode($request->get_json_params())));
    if(is_wp_error($response)||wp_remote_retrieve_response_code($response)!==200){return new WP_Error('denied','Grant denied',array('status'=>403));}
    $grant=json_decode(wp_remote_retrieve_body($response),true);
    if(!is_array($grant)||empty($grant['wordpress_user_id'])){return new WP_Error('invalid','Invalid grant',array('status'=>403));}
    wp_set_auth_cookie((int)$grant['wordpress_user_id'],false,is_ssl());
    return array('redirect'=>admin_url());
  }));
});
`
func(runtime *LinuxApplicationRuntime)InstallAutologinBridge(ctx context.Context,request AutologinBridgeRequest)(ExecutionReceipt,error){if request.Validate()!=nil||request.BridgeDigest!=linuxApplicationDigest([]byte(cyberPanelAutologinBridge)){return ExecutionReceipt{},ErrRecipeUntrusted};scope,err:=runtime.resolve(ctx,request.Scope);if err!=nil{return ExecutionReceipt{},err};directory:=filepath.Join(scope.root,"wp-content","mu-plugins");if err=os.MkdirAll(directory,0750);err!=nil{return ExecutionReceipt{},err};path:=filepath.Join(directory,"cyberpanel-autologin.php");if err=os.WriteFile(path,[]byte(cyberPanelAutologinBridge),0640);err!=nil{return ExecutionReceipt{},err};if err=os.Chown(path,int(scope.binding.UID),int(scope.binding.GID));err!=nil{return ExecutionReceipt{},err};if _,stderr,_,err:=runtime.wp(ctx,scope,nil,1<<20,"option","update","cyberpanel_autologin_endpoint",request.Endpoint);err!=nil{return ExecutionReceipt{},fmt.Errorf("configure autologin bridge: %w: %s",err,stderr)};return receiptForApplication("install_autologin_bridge",request.Scope,request.InstallationID,request,request.BridgeDigest,"","",true),nil}
func(runtime *LinuxApplicationRuntime)RemoveAutologinBridge(ctx context.Context,request AutologinBridgeRequest)(ExecutionReceipt,error){scope,err:=runtime.resolve(ctx,request.Scope);if err!=nil{return ExecutionReceipt{},err};path:=filepath.Join(scope.root,"wp-content","mu-plugins","cyberpanel-autologin.php");if err=os.Remove(path);err!=nil&&!errors.Is(err,os.ErrNotExist){return ExecutionReceipt{},err};_,_,_,_=runtime.wp(ctx,scope,nil,1<<20,"option","delete","cyberpanel_autologin_endpoint");return receiptForApplication("remove_autologin_bridge",request.Scope,request.InstallationID,request,"removed","","",true),nil}

func applicationShadowToken(installation InstallationID,release ReleaseID)string{return "shadow-"+linuxApplicationDigest([]byte(string(installation)+"\x00"+string(release)))[:40]}
func(runtime *LinuxApplicationRuntime)routeBinding(ctx context.Context,siteID SiteID)(LinuxApplicationSiteBinding,string,error){if runtime==nil||runtime.Resolver==nil||!validID(string(siteID)){return LinuxApplicationSiteBinding{},"",ErrInvalid};binding,err:=runtime.Resolver.ResolveApplicationSite(ctx,siteID);if err!=nil{return LinuxApplicationSiteBinding{},"",err};if binding.SiteKey==""||!strings.HasPrefix(binding.SiteKey,"s-")||binding.UID<1000||binding.GID!=binding.UID||binding.Generation==0{return LinuxApplicationSiteBinding{},"",ErrPolicyDenied};generationRoot:=filepath.Join(linuxApplicationSitesRoot,binding.SiteKey,"roots","g"+strconv.FormatUint(binding.Generation,10));releases:=filepath.Join(generationRoot,"releases");if err=validateLinuxApplicationRoot(generationRoot,filepath.Join(releases,"current"),binding);err!=nil{return LinuxApplicationSiteBinding{},"",err};return binding,releases,nil}
func(runtime *LinuxApplicationRuntime)shadowScope(scope linuxApplicationScope,token string)(linuxApplicationScope,error){if !strings.HasPrefix(token,"shadow-")||len(token)!=47{return linuxApplicationScope{},ErrPolicyDenied};releases:=filepath.Dir(scope.root);if filepath.Base(scope.root)!="current"{releases=filepath.Join(linuxApplicationSitesRoot,scope.binding.SiteKey,"roots","g"+strconv.FormatUint(scope.binding.Generation,10),"releases")};root:=filepath.Join(releases,".app-"+token);info,err:=os.Lstat(root);if err!=nil||!info.IsDir()||info.Mode()&os.ModeSymlink!=0{return linuxApplicationScope{},ErrNotFound};scope.root=root;return scope,nil}
func(runtime *LinuxApplicationRuntime)CreateShadowRoute(ctx context.Context,siteID SiteID,installation InstallationID,release ReleaseID)(string,error){if !validID(string(installation))||!validID(string(release)){return "",ErrInvalid};binding,releases,err:=runtime.routeBinding(ctx,siteID);if err!=nil{return "",err};token:=applicationShadowToken(installation,release);target:=filepath.Join(releases,".app-"+token);if info,statErr:=os.Lstat(target);statErr==nil{if !info.IsDir()||info.Mode()&os.ModeSymlink!=0{return "",ErrConflict};return token,nil}else if !errors.Is(statErr,os.ErrNotExist){return "",statErr};if err=os.Mkdir(target,0750);err!=nil{return "",err};if err=os.Chown(target,int(binding.UID),int(binding.GID));err!=nil{return "",err};scope:=linuxApplicationScope{binding:binding,root:releases};if _,stderr,_,err:=runtime.command(ctx,scope,"/usr/bin/cp",nil,4<<20,"-a","--",filepath.Join(releases,"current")+"/.",target);err!=nil{_ = os.RemoveAll(target);return "",fmt.Errorf("prepare application shadow: %w: %s",err,stderr)};return token,nil}
