type applicationRouteSwap struct{InstallationID InstallationID `json:"installation_id"`;TargetRelease ReleaseID `json:"target_release"`;Shadow string `json:"shadow"`;Rollback string `json:"rollback"`}
func(runtime *LinuxApplicationRuntime)ActivateReleaseRoute(ctx context.Context,siteID SiteID,installation InstallationID,release ReleaseID,shadow string)error{if shadow!=applicationShadowToken(installation,release){return ErrPolicyDenied};_,releases,err:=runtime.routeBinding(ctx,siteID);if err!=nil{return err};current:=filepath.Join(releases,"current");candidate:=filepath.Join(releases,".app-"+shadow);rollback:=".app-rollback-"+linuxApplicationDigest([]byte(string(installation)+"\x00"+string(release)))[:40];rollbackPath:=filepath.Join(releases,rollback);if _,err=os.Lstat(candidate);err!=nil{return ErrNotFound};if _,err=os.Lstat(rollbackPath);err==nil{return ErrConflict}else if !errors.Is(err,os.ErrNotExist){return err};if err=os.Rename(current,rollbackPath);err!=nil{return err};if err=os.Rename(candidate,current);err!=nil{_ = os.Rename(rollbackPath,current);return err};state:=applicationRouteSwap{installation,release,shadow,rollback};encoded,_:=json.Marshal(state);statePath:=filepath.Join(releases,".application-route-swap.json");if err=os.WriteFile(statePath,encoded,0600);err!=nil{_ = os.Rename(current,candidate);_ = os.Rename(rollbackPath,current);return err};return nil}
func(runtime *LinuxApplicationRuntime)RestoreReleaseRoute(ctx context.Context,siteID SiteID,installation InstallationID,release ReleaseID)error{if !validID(string(installation))||!validID(string(release)){return ErrInvalid};_,releases,err:=runtime.routeBinding(ctx,siteID);if err!=nil{return err};statePath:=filepath.Join(releases,".application-route-swap.json");encoded,err:=os.ReadFile(statePath);if errors.Is(err,os.ErrNotExist){return nil};if err!=nil{return err};var state applicationRouteSwap;if json.Unmarshal(encoded,&state)!=nil||state.InstallationID!=installation||!strings.HasPrefix(state.Shadow,"shadow-")||!strings.HasPrefix(state.Rollback,".app-rollback-"){return ErrIntegrity};current:=filepath.Join(releases,"current");failed:=filepath.Join(releases,".app-"+state.Shadow);rollback:=filepath.Join(releases,state.Rollback);if err=os.Rename(current,failed);err!=nil{return err};if err=os.Rename(rollback,current);err!=nil{_ = os.Rename(failed,current);return err};return os.Remove(statePath)}

